import type { SDKUserMessage } from '@thyrox/headless-sdk/agentSdkTypes.js'
import { fromArray } from '@thyrox/config/generators'
import { jsonStringify } from '@thyrox/local-observability/slowOperations.js'
import { RemoteIO } from './remoteIO.js'
import { StructuredIO } from './structuredIO.js'

export function getStructuredIO(
  inputPrompt: string | AsyncIterable<string>,
  options: {
    sdkUrl: string | undefined
    replayUserMessages?: boolean
  },
): StructuredIO {
  let inputStream: AsyncIterable<string>
  if (typeof inputPrompt === 'string') {
    if (inputPrompt.trim() !== '') {
      const userMessage = {
        type: 'user' as const,
        content: inputPrompt,
        uuid: '',
        session_id: '',
        message: {
          role: 'user' as const,
          content: inputPrompt,
        },
        parent_tool_use_id: null,
      }
      inputStream = fromArray([jsonStringify(userMessage satisfies SDKUserMessage)])
    } else {
      inputStream = fromArray([])
    }
  } else {
    inputStream = inputPrompt
  }

  return options.sdkUrl
    ? new RemoteIO(options.sdkUrl, inputStream, options.replayUserMessages)
    : new StructuredIO(inputStream, options.replayUserMessages)
}

import memoize from 'lodash-es/memoize.js'
import type { HookEvent } from './_deps.js'
import {
  clearRegisteredPluginHooks,
  getRegisteredHooks,
  registerHookCallbacks,
} from './_deps.js'
import type { LoadedPlugin } from './types.js'
import { logForDebugging } from './_deps.js'
import { settingsChangeDetector } from '../settings/changeDetector.js'
import {
  getSettings,
  getSettingsForSource,
} from '../settings/settings.js'
import type { PluginHookMatcher } from '../settings/types.js'
import { jsonStringify } from './_deps.js'
import { clearPluginCache, loadAllPluginsCacheOnly } from './pluginLoader.js'

// Track if hot reload subscription is set up
let hotReloadSubscribed = false

// Snapshot of enabledPlugins for change detection in hot reload
let lastPluginSettingsSnapshot: string | undefined

/**
 * Convert plugin hooks configuration to native matchers with plugin context
 */
function convertPluginHooksToMatchers(
  plugin: LoadedPlugin,
): Record<HookEvent, PluginHookMatcher[]> {
  // Literal sin anotación de tipo: al no ser 'fresh' donde se declara con
  // tipo, el chequeo de propiedades excedentes no aplica y las claves fuera
  // de HookEvent no rompen la asignación estructural de abajo.
  const pluginMatchersLiteral = {
    PreToolUse: [],
    PostToolUse: [],
    PostToolUseFailure: [],
    PermissionDenied: [],
    Notification: [],
    UserPromptSubmit: [],
    SessionStart: [],
    SessionEnd: [],
    Stop: [],
    StopFailure: [],
    SubagentStart: [],
    SubagentStop: [],
    PreCompact: [],
    PostCompact: [],
    PermissionRequest: [],
    Setup: [],
    TeammateIdle: [],
    TaskCreated: [],
    TaskCompleted: [],
    Elicitation: [],
    ElicitationResult: [],
    ConfigChange: [],
    WorktreeCreate: [],
    WorktreeRemove: [],
    InstructionsLoaded: [],
    CwdChanged: [],
    FileChanged: [],
  }
  const pluginMatchers: Record<HookEvent, PluginHookMatcher[]> = pluginMatchersLiteral

  if (!plugin.hooksConfig) {
    return pluginMatchers
  }

  // Process each hook event - pass through all hook types with plugin context
  for (const [event, matchers] of Object.entries(plugin.hooksConfig)) {
    const hookEvent = event as HookEvent
    if (!pluginMatchers[hookEvent]) {
      continue
    }

    for (const matcher of matchers) {
      if (matcher.hooks.length > 0) {
        pluginMatchers[hookEvent].push({
          matcher: matcher.matcher,
          hooks: matcher.hooks,
          pluginRoot: plugin.path,
          pluginName: plugin.name,
          pluginId: plugin.source,
        })
      }
    }
  }

  return pluginMatchers
}

/**
 * Load and register hooks from all enabled plugins
 */
export const loadPluginHooks = memoize(async (): Promise<void> => {
  const { enabled } = await loadAllPluginsCacheOnly()
  // Mismo motivo que convertPluginHooksToMatchers: literal sin anotación
  // para que la asignación de abajo no dispare el chequeo de excedentes.
  const allPluginHooksLiteral = {
    PreToolUse: [],
    PostToolUse: [],
    PostToolUseFailure: [],
    PermissionDenied: [],
    Notification: [],
    UserPromptSubmit: [],
    SessionStart: [],
    SessionEnd: [],
    Stop: [],
    StopFailure: [],
    SubagentStart: [],
    SubagentStop: [],
    PreCompact: [],
    PostCompact: [],
    PermissionRequest: [],
    Setup: [],
    TeammateIdle: [],
    TaskCreated: [],
    TaskCompleted: [],
    Elicitation: [],
    ElicitationResult: [],
    ConfigChange: [],
    WorktreeCreate: [],
    WorktreeRemove: [],
    InstructionsLoaded: [],
    CwdChanged: [],
    FileChanged: [],
  }
  const allPluginHooks: Record<HookEvent, PluginHookMatcher[]> = allPluginHooksLiteral

  // Process each enabled plugin
  for (const plugin of enabled) {
    if (!plugin.hooksConfig) {
      continue
    }

    logForDebugging(`Loading hooks from plugin: ${plugin.name}`)
    const pluginMatchers = convertPluginHooksToMatchers(plugin)

    // Merge plugin hooks into the main collection
    for (const event of Object.keys(pluginMatchers) as HookEvent[]) {
      allPluginHooks[event].push(...pluginMatchers[event])
    }
  }

  // Clear-then-register as an atomic pair. Previously the clear lived in
  // clearPluginHookCache(), which meant any clearAllCaches() call (from
  // /plugins UI, pluginInstallationHelpers, thinkback, etc.) wiped plugin
  // hooks from STATE.registeredHooks and left them wiped until someone
  // happened to call loadPluginHooks() again. SessionStart explicitly awaits
  // loadPluginHooks() before firing so it always re-registered; Stop has no
  // such guard, so plugin Stop hooks silently never fired after any plugin
  // management operation (gh-29767). Doing the clear here makes the swap
  // atomic — old hooks stay valid until this point, new hooks take over.
  clearRegisteredPluginHooks()
  registerHookCallbacks(allPluginHooks)

  const totalHooks = Object.values(allPluginHooks).reduce(
    (sum, matchers) => sum + matchers.reduce((s, m) => s + m.hooks.length, 0),
    0,
  )
  logForDebugging(
    `Registered ${totalHooks} hooks from ${enabled.length} plugins`,
  )
})

export function clearPluginHookCache(): void {
  // Only invalidate the memoize — do NOT wipe STATE.registeredHooks here.
  // Wiping here left plugin hooks dead between clearAllCaches() and the next
  // loadPluginHooks() call, which for Stop hooks might never happen
  // (gh-29767). The clear now lives inside loadPluginHooks() as an atomic
  // clear-then-register, so old hooks stay valid until the fresh load swaps
  // them out.
  loadPluginHooks.cache?.clear?.()
}

/**
 * Remove hooks from plugins no longer in the enabled set, without adding
 * hooks from newly-enabled plugins. Called from clearAllCaches() so
 * uninstalled/disabled plugins stop firing hooks immediately (gh-36995),
 * while newly-enabled plugins wait for /reload-plugins — consistent with
 * how commands/agents/MCP behave.
 *
 * The full swap (clear + register all) still happens via loadPluginHooks(),
 * which /reload-plugins awaits.
 */
export async function pruneRemovedPluginHooks(): Promise<void> {
  // Early return when nothing to prune — avoids seeding the loadAllPluginsCacheOnly
  // memoize in test/preload.ts beforeEach (which clears registeredHooks).
  if (!getRegisteredHooks()) return
  const { enabled } = await loadAllPluginsCacheOnly()
  const enabledRoots = new Set(enabled.map(p => p.path))

  // Re-read after the await: a concurrent loadPluginHooks() (hot-reload)
  // could have swapped STATE.registeredHooks during the gap. Holding the
  // pre-await reference would compute survivors from stale data.
  const current = getRegisteredHooks()
  if (!current) return

  // Collect plugin hooks whose pluginRoot is still enabled, then swap via
  // the existing clear+register pair (same atomic-pair pattern as
  // loadPluginHooks above). Callback hooks are preserved by
  // clearRegisteredPluginHooks; we only need to re-register survivors.
  const survivors: Partial<Record<HookEvent, PluginHookMatcher[]>> = {}
  for (const [event, matchers] of Object.entries(current)) {
    const kept = matchers.filter(
      (m: { pluginRoot: string }): m is PluginHookMatcher =>
        'pluginRoot' in m && enabledRoots.has(m.pluginRoot),
    )
    if (kept.length > 0) survivors[event as HookEvent] = kept
  }

  clearRegisteredPluginHooks()
  registerHookCallbacks(survivors)
}

/**
 * Reset hot reload subscription state. Only for testing.
 */
export function resetHotReloadState(): void {
  hotReloadSubscribed = false
  lastPluginSettingsSnapshot = undefined
}

/**
 * Build a stable string snapshot of the settings that feed into
 * `loadAllPluginsCacheOnly()` for change detection. Sorts keys so comparison is
 * deterministic regardless of insertion order.
 *
 * Hashes FOUR fields — not just enabledPlugins — because the memoized
 * loadAllPluginsCacheOnly() also reads strictKnownMarketplaces, blockedMarketplaces
 * (pluginLoader.ts:1933 via getBlockedMarketplaces), and
 * extraKnownMarketplaces. If remote managed settings set only one of
 * these (no enabledPlugins), a snapshot keyed only on enabledPlugins
 * would never diff, the listener would skip, and the memoized result
 * would retain the pre-remote marketplace allow/blocklist.
 * See #23085 / #23152 poisoned-cache discussion (Slack C09N89L3VNJ).
 */
// Exported for testing — the listener at setupPluginHookHotReload uses this
// for change detection; tests verify it diffs on the fields that matter.
export function getPluginAffectingSettingsSnapshot(): string {
  const merged = getSettings()
  const policy = getSettingsForSource('policySettings')
  // Key-sort the two Record fields so insertion order doesn't flap the hash.
  // Array fields (strictKnownMarketplaces, blockedMarketplaces) have
  // schema-stable order.
  const sortKeys = <T extends Record<string, unknown>>(o: T | undefined) =>
    o ? Object.fromEntries(Object.entries(o).sort()) : {}
  return jsonStringify({
    enabledPlugins: sortKeys(merged.enabledPlugins),
    extraKnownMarketplaces: sortKeys(merged.extraKnownMarketplaces),
    strictKnownMarketplaces: policy?.strictKnownMarketplaces ?? [],
    blockedMarketplaces: policy?.blockedMarketplaces ?? [],
  })
}

/**
 * Set up hot reload for plugin hooks when remote settings change.
 * When policySettings changes (e.g., from remote managed settings),
 * compares the plugin-affecting settings snapshot and only reloads if it
 * actually changed.
 */
export function setupPluginHookHotReload(): void {
  if (hotReloadSubscribed) {
    return
  }
  hotReloadSubscribed = true

  // Capture the initial snapshot so the first policySettings change can compare
  lastPluginSettingsSnapshot = getPluginAffectingSettingsSnapshot()

  settingsChangeDetector.subscribe(source => {
    if (source === 'policySettings') {
      const newSnapshot = getPluginAffectingSettingsSnapshot()
      if (newSnapshot === lastPluginSettingsSnapshot) {
        logForDebugging(
          'Plugin hooks: skipping reload, plugin-affecting settings unchanged',
        )
        return
      }

      lastPluginSettingsSnapshot = newSnapshot
      logForDebugging(
        'Plugin hooks: reloading due to plugin-affecting settings change',
      )

      // Clear all plugin-related caches
      clearPluginCache('loadPluginHooks: plugin-affecting settings changed')
      clearPluginHookCache()

      // Reload hooks (fire-and-forget, don't block)
      void loadPluginHooks()
    }
  })
}

/**
 * Puerta de permisos (T-008, T-025, T-026, T-027).
 *
 * Tres capas, y el orden entre ellas es lo que decide:
 *
 * 1. **Confinamiento de rutas** — una ruta fuera de los directorios
 *    declarados se deniega antes de mirar nada más. Va primera porque una
 *    regla `allow` no debe poder sacar al agente del árbol.
 * 2. **Reglas por patrón** — `Bash(git push:*)`, `Read(src/**)`. `deny` gana
 *    sobre `allow` aunque las dos casen: en una puerta, la negativa manda.
 * 3. **Capacidad** — `read`/`write`/`execute`, con el modo por encima.
 *
 * Y siempre se devuelve **qué regla decidió**. Un `deny` sin regla nombrada es
 * inexplicable para quien lo recibe, y lo recibe un modelo que no puede
 * preguntar.
 */
import { isAbsolute, relative, resolve } from 'node:path'

export type Decision = 'allow' | 'ask' | 'deny'
export type Capability = 'read' | 'write' | 'execute'
export type Mode = 'default' | 'acceptEdits' | 'bypass'

export type PermissionPolicy = {
  defaultMode?: Mode
  read?: Decision
  write?: Decision
  execute?: Decision
  default?: Decision
  allow?: string[]
  deny?: string[]
  additionalDirectories?: string[]
}

export type Verdict = { decision: Decision; rule?: string; reason?: string }

/**
 * La decisión por capacidad, con el modo por encima.
 *
 * `acceptEdits` sólo alcanza a la escritura — es su sentido: aceptar ediciones
 * sin preguntar, no ejecutar comandos sin preguntar. `bypass` alcanza a todo,
 * incluso a lo denegado, porque para eso existe.
 */
export function decide(policy: PermissionPolicy | undefined, capability: Capability, interactive = false): Decision {
  const modo = policy?.defaultMode ?? 'default'
  if (modo === 'bypass') return 'allow'
  const p = policy?.[capability] ?? policy?.default ?? 'allow'
  if (modo === 'acceptEdits' && capability === 'write') return 'allow'
  if (p === 'ask' && !interactive) return 'deny'
  return p
}

/** `Bash(git push:*)` da herramienta `Bash` y patrón `git push:*`. */
function partirRegla(rule: string): { tool: string; pattern?: string } {
  const m = /^([A-Za-z_][A-Za-z0-9_]*)\((.*)\)$/.exec(rule)
  if (m === null) return { tool: rule }
  const tool = m[1]
  const pattern = m[2]
  if (tool === undefined) return { tool: rule }
  return pattern === undefined ? { tool } : { tool, pattern }
}

/** El argumento sobre el que casa el patrón: el comando o la ruta, según la herramienta. */
function objetivo(input: Record<string, unknown>): string {
  for (const clave of ['command', 'file_path', 'path', 'pattern', 'url']) {
    const v = input[clave]
    if (typeof v === 'string') return v
  }
  return ''
}

function globARegExp(patron: string): RegExp {
  // `**` cruza separadores; `*` no. Se traduce partiendo por `**` en vez de
  // usar un marcador intermedio: un marcador que aparezca en el patrón —o que
  // sea un byte de control, como ocurrió aquí— produce una regla que no casa
  // nada y no lo dice.
  const escapar = (s: string) => s.replace(/[.+^${}()|[\]\\]/g, '\\$&')
  const cuerpo = patron
    .split('**')
    .map((tramo) => escapar(tramo).replace(/\*/g, '[^/]*'))
    .join('.*')
  return new RegExp(`^${cuerpo}$`)
}

/**
 * ¿Esta regla casa esta llamada?
 *
 * `git push:*` es la forma del cliente para «el comando empieza por `git
 * push`»; los dos puntos separan el prefijo del comodín. Un patrón sin esa
 * forma se trata como glob, que es lo que sirve para rutas.
 */
export function matchesRule(rule: string, toolName: string, input: Record<string, unknown>): boolean {
  const { tool, pattern } = partirRegla(rule)
  if (tool !== toolName) return false
  if (pattern === undefined || pattern === '*') return true
  const valor = objetivo(input)
  const prefijo = /^(.*):\*$/.exec(pattern)
  if (prefijo !== null) {
    const sufijo = prefijo[1]
    if (sufijo !== undefined) return valor === sufijo || valor.startsWith(sufijo)
  }
  return globARegExp(pattern).test(valor)
}

/** ¿La ruta cae dentro de alguno de los directorios declarados? Se resuelve antes de comparar. */
export function confinedTo(path: string, directories: string[]): boolean {
  if (directories.length === 0) return true
  const absoluta = resolve(path)
  return directories.some((d) => {
    const raiz = resolve(d)
    const rel = relative(raiz, absoluta)
    // fuera si sube (`..`) o si es otra rama absoluta; `repo-otro` no está en `repo`
    return rel === '' || (!rel.startsWith('..') && !isAbsolute(rel))
  })
}

/** Las tres capas, en su orden, con la regla que decidió. */
export function evaluate(
  policy: PermissionPolicy | undefined,
  toolName: string,
  capability: Capability,
  input: Record<string, unknown>,
  interactive = false,
): Verdict {
  const dirs = policy?.additionalDirectories ?? []
  const ruta = typeof input.file_path === 'string' ? input.file_path : typeof input.path === 'string' ? input.path : undefined
  if (ruta && !confinedTo(ruta, dirs)) {
    return { decision: 'deny', reason: `la ruta ${ruta} queda fuera de los directorios declarados` }
  }
  const negada = (policy?.deny ?? []).find((r) => matchesRule(r, toolName, input))
  if (negada) return { decision: 'deny', rule: negada, reason: `denegado por la regla ${negada}` }
  const permitida = (policy?.allow ?? []).find((r) => matchesRule(r, toolName, input))
  if (permitida) return { decision: 'allow', rule: permitida }
  return { decision: decide(policy, capability, interactive), reason: `por capacidad ${capability}` }
}

// Las transiciones de modo y el estado del modo automatico viven en
// `permissionSetup.ts`; el barrel no los publicaba y sus consumidores fallaban
// con TS2305.
export {
  getAutoModeUnavailableNotification,
  getAutoModeUnavailableReason,
  isAutoModeGateEnabled,
  isBypassPermissionsModeDisabled,
  transitionPermissionMode,
} from './permissionSetup.js'

// La decision de permiso de una llamada a herramienta. La fuente la publica
// desde la raiz del paquete (`index.ts`), y el SDK headless la importa de ahi.
export { hasPermissionsToUseTool } from './permissions.js'

/**
 * Resolve a free-text token to a directory that lives in the agent
 * registry (a known repo or path).
 *
 * Source: ant zi8 (5092.js:688-698) + ms3 (5092.js:676-683).
 *
 * Scans the query for `@name` tokens; if `name` matches an entry in
 * `agentMap` AND that agent has a `cwd`, returns it. Otherwise undefined.
 *
 * Used by the dispatch flow so `@my-agent fix the bug` can route to the
 * correct working tree.
 */

import type { ResolvedAgent } from '@thyrox/tool-registry/tools/AgentTool/agentDisplay.js'

const AT_REF_RE = /(?:^|\s)@(\S+)/g

interface AgentLike {
  name: string
  cwd?: string
}

/** Source: ant zi8. */
export function extractRepoCwd<T extends AgentLike | ResolvedAgent>(
  query: string,
  agentMap: Record<string, T>,
  fleetAgents: readonly { name: string }[] = [],
): T | undefined {
  const seenAgentNames = new Set(fleetAgents.map(a => a.name.toLowerCase()))
  const keys = Object.keys(agentMap)
  for (const match of query.matchAll(AT_REF_RE)) {
    const name = (match[1] ?? '').toLowerCase()
    if (seenAgentNames.has(name)) continue
    const key = keys.find(k => k.toLowerCase() === name)
    if (key !== undefined) return agentMap[key]
  }
  return undefined
}
